"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$PKG = "E:'"\\VPS\\reports\\owner-admin-cutover-final-20260814-recovery-v1-fl16\"
"'$sumsLines = Get-Content (Join-Path $PKG "11_SHA256SUMS")
$computed = @{}
foreach ($line in $sumsLines) {
  $parts = $line -split "  ", 2
  if ($parts.Count -eq 2) { $computed[$parts[1].Trim()] = $parts[0].Trim() }
}

$manifestContent = Get-Content (Join-Path $PKG "10_MANIFEST.json") -Raw | ConvertFrom-Json
$allOk = $true
foreach ($entry in $manifestContent.files) {
  $mHash = $entry.sha256
  $sHash = $computed[$entry.path]
  $liveHash = (Get-FileHash (Join-Path $PKG ($entry.path.Replace("/","'"\\\"))) -Algorithm SHA256).Hash.ToLower()
  "'$mEqS = $mHash -eq $sHash
  $mEqL = $mHash -eq $liveHash
  $ok = if ($mEqS -and $mEqL) { "OK" } else { $allOk = $false; "FAIL" }
  Write-Output "$ok  $($entry.path)  manifest==sums=$mEqS  manifest==live=$mEqL"
}
Write-Output ""
Write-Output "PYC0 cross-check all OK: $allOk"
Write-Output "Manifest file_count field: $($manifestContent.file_count)"
Write-Output "Manifest files array count: $($manifestContent.files.Count)"'

